import datetime
from collections.abc import Iterable


def _to_cents(amount):
    """Convert a dollar amount (float/str/decimal-like) to integer cents."""
    try:
        # round() avoids common float issues; int() converts to whole cents.
        return int(round(float(amount) * 100))
    except (TypeError, ValueError) as e:
        raise ValueError("payment amount must be numeric") from e


def _extract_amount_and_date(payment):
    """Normalize supported payment shapes.

    Accepted:
      - numeric amount (assumes no date)
      - dict with keys: amount/dollars and optional date/on
      - tuple/list: (amount, date) where date can be None
    """
    # Default: amount only
    amount = payment
    on = None

    if isinstance(payment, dict):
        amount = payment.get("amount", payment.get("dollars", payment.get("cents")))
        on = payment.get("date", payment.get("on", None))
    elif isinstance(payment, (tuple, list)):
        if len(payment) < 1:
            raise ValueError("payment tuple/list must contain an amount")
        amount = payment[0]
        if len(payment) >= 2:
            on = payment[1]

    return amount, on


def record_payments(ledger, payments):
    """Post each payment in `payments` to the ledger's 'cash' account.

    - `payments` items are dollar amounts (floats) or basic structures containing
      an amount and optional date.
    - Dollars are converted to cents as an integer using round(amount*100).
    - If a payment provides no date (or date is None), the entry is posted
      without the `on=` argument.
    """
    if payments is None:
        return

    # Allow single numeric payment
    if isinstance(payments, (int, float, str, dict, tuple, list)):
        payments = [payments]

    if not isinstance(payments, Iterable) or isinstance(payments, (str, bytes)):
        raise ValueError("payments must be an iterable of payment objects")

    for payment in payments:
        amount, on = _extract_amount_and_date(payment)
        cents = _to_cents(amount)

        # ledger.post signature is (account, amount, on=None)
        # If we weren't given a date, omit `on` entirely.
        if on is None:
            ledger.post("cash", cents)
        else:
            if not isinstance(on, datetime.date):
                raise ValueError("payment date must be a datetime.date or None")
            ledger.post("cash", cents, on=on)

