from decimal import Decimal, ROUND_HALF_UP


def _to_cents(dollars: float) -> int:
    d = Decimal(str(dollars))
    return int((d * Decimal('100')).to_integral_value(rounding=ROUND_HALF_UP))


def refund(ledger, account, dollars):
    # validation
    if ledger is None:
        raise TypeError('ledger is required')
    if not isinstance(account, str) or not account:
        raise TypeError('account must be a non-empty string')
    if isinstance(dollars, bool):
        raise TypeError('dollars must be a number')
    if not isinstance(dollars, (int, float, Decimal)):
        raise TypeError('dollars must be a number')
    # convert to cents
    cents = _to_cents(dollars)
    if cents < 0:
        raise ValueError('dollars must be non-negative')
    # if 0, still allow posting? choose not to post to avoid noise
    if cents != 0:
        ledger.post(account, -cents, on=datetime.date.today())
    return cents

